import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = pd.NaT

    # Filter events strictly after watermark
    if pd.isna(high_ts):
        events = cdc.copy()
    else:
        events = cdc[cdc["event_ts"] > high_ts].copy()

    # Sort events per user by (event_ts, event_seq)
    events = events.sort_values(by=["user_id", "event_ts", "event_seq"],
                                 kind="mergesort")

    # Build initial state dict from target_snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    seven_days = timedelta(days=7)

    for _, ev in events.iterrows():
        uid = ev["user_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        email = ev["email"]

        cur = state.get(uid)

        if op == "D":
            if cur is not None:
                preserved_email = cur["email"]
            else:
                preserved_email = email
            state[uid] = {
                "email": preserved_email,
                "status": "DELETED",
                "status_ts": ts,
            }
        elif op == "U":
            if cur is None or cur["status"] == "ACTIVE":
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            else:
                # cur status == 'DELETED'
                if ts > cur["status_ts"] + seven_days:
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                # else discard, no change
        # unknown ops ignored

    rows = []
    for uid, s in state.items():
        rows.append({
            "user_id": uid,
            "email": s["email"],
            "status": s["status"],
            "status_ts": s["status_ts"],
        })

    result = pd.DataFrame(rows, columns=["user_id", "email", "status", "status_ts"])

    if len(result) > 0:
        result["user_id"] = result["user_id"].astype("int64")
        result["email"] = result["email"].astype(str)
        result["status"] = result["status"].astype(str)
        result["status_ts"] = pd.to_datetime(result["status_ts"])

    return {"new_snapshot": result}
